changeSet.sql:
CREATE TABLE claims ( id UUID PRIMARY KEY, claim_number VARCHAR(80) NOT NULL, policy_id UUID NOT NULL, insurance_company_id UUID NOT NULL, patient_profile_id UUID NOT NULL, hospital_id UUID NULL, doctor_profile_id UUID NULL, status VARCHAR(40) NOT NULL, service_type VARCHAR(80) NOT NULL, treatment_date DATE NOT NULL, claim_amount DECIMAL(14,2) NOT NULL, approved_amount DECIMAL(14,2) NULL, covered_amount DECIMAL(14,2) NOT NULL, patient_pay_amount DECIMAL(14,2) NOT NULL, payout_recipient_type VARCHAR(30) NOT NULL, policy_reservation_id UUID NULL, diagnosis_code VARCHAR(80) NULL, reason TEXT NULL, notes TEXT NULL, risk_score INT NULL, risk_level VARCHAR(30) NULL, fraud_score INT NULL, fraud_level VARCHAR(30) NULL, fraud_passed BOOLEAN NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL );
CREATE TABLE claim_items ( id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), description VARCHAR(500) NOT NULL, service_code VARCHAR(80) NULL, amount DECIMAL(14,2) NOT NULL, quantity INT NOT NULL, service_date DATE NULL, document_id UUID NULL, created_at TIMESTAMP NOT NULL, updated_at TIMESTAMP NOT NULL );
CREATE TABLE claim_document_references ( id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), document_id UUID NOT NULL, document_type VARCHAR(80) NOT NULL, required BOOLEAN NOT NULL, status VARCHAR(30) NOT NULL, created_at TIMESTAMP NOT NULL );
CREATE TABLE claim_decisions ( id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), decision VARCHAR(50) NOT NULL, decided_by UUID NOT NULL, reason TEXT NOT NULL, approved_amount DECIMAL(14,2) NULL, created_at TIMESTAMP NOT NULL );
CREATE TABLE claim_status_history ( id UUID PRIMARY KEY, claim_id UUID NOT NULL REFERENCES claims(id), from_status VARCHAR(40) NULL, to_status VARCHAR(40) NOT NULL, changed_by_user_id UUID NULL, reason TEXT NULL, created_at TIMESTAMP NOT NULL );
CREATE UNIQUE INDEX uk_claims_claim_number ON claims(claim_number); CREATE INDEX idx_claims_policy_id ON claims(policy_id); CREATE INDEX idx_claims_insurance_company_id ON claims(insurance_company_id); CREATE INDEX idx_claims_patient_profile_id ON claims(patient_profile_id); CREATE INDEX idx_claims_hospital_id ON claims(hospital_id); CREATE INDEX idx_claims_status ON claims(status); CREATE INDEX idx_claims_treatment_date ON claims(treatment_date); CREATE INDEX idx_claim_items_claim_id ON claim_items(claim_id); CREATE INDEX idx_claim_document_references_claim_id ON claim_document_references(claim_id); CREATE INDEX idx_claim_decisions_claim_id ON claim_decisions(claim_id); CREATE INDEX idx_claim_status_history_claim_id ON claim_status_history(claim_id);
